"""Shortest Path in a Weighted Graph — Dijkstra with an early exit.

Time: O(E log V)   Space: O(V + E)
"""
import heapq
from typing import List


class Solution:
    def shortestPath(self, n: int, edges: List[List[int]], src: int, dst: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        INF = float("inf")
        dist = [INF] * n
        dist[src] = 0
        heap = [(0, src)]
        while heap:
            d, node = heapq.heappop(heap)
            if node == dst:
                return d
            if d > dist[node]:
                continue
            for nxt, weight in graph[node]:
                if d + weight < dist[nxt]:
                    dist[nxt] = d + weight
                    heapq.heappush(heap, (dist[nxt], nxt))
        return -1
